import { Controller } from "@hotwired/stimulus"
import { post, destroy } from "@rails/request.js"

const CARD = "article[data-card-triage-url]"
const COLUMN = "[data-drop-status]"
const DRAGGED = "drag-and-drop__dragged-item"
const HOVER = "drag-and-drop__hover-container"

export default class extends Controller {
  #card
  #hoverColumn
  #saves = Promise.resolve()

  disconnect() {
    this.end()
  }

  // Enable native dragging only inside an editable board, including newly paginated cards.
  prepare({ target }) {
    const card = target.closest(CARD)
    if (card) card.draggable = !card.hasAttribute("aria-busy") && matchMedia("(min-width: 640px)").matches
  }

  start({ target, dataTransfer }) {
    if (!target.matches(CARD) || !target.draggable) return

    this.#card = target
    dataTransfer.effectAllowed = "move"
    dataTransfer.setData("text/plain", target.id)
    target.classList.add(DRAGGED)
  }

  over(event) {
    const column = this.#destination(event.target)
    this.#highlight(column)
    if (column) {
      event.preventDefault()
      event.dataTransfer.dropEffect = "move"
    }
  }

  leave({ relatedTarget }) {
    if (!this.#hoverColumn?.contains(relatedTarget)) this.#highlight(null)
  }

  drop(event) {
    const card = this.#card
    const column = this.#destination(event.target)
    this.end()

    if (column) {
      event.preventDefault()
      this.#move(card, column)
    }
  }

  end() {
    this.#card?.classList.remove(DRAGGED)
    this.#card = null
    this.#highlight(null)
  }

  #destination(target) {
    const column = target.closest(COLUMN)
    if (this.#card && column && !column.contains(this.#card) && column.querySelector(".cards__list")) return column
  }

  #highlight(column) {
    if (this.#hoverColumn !== column) {
      this.#hoverColumn?.classList.remove(HOVER)
      column?.classList.add(HOVER)
      this.#hoverColumn = column
    }
  }

  #move(card, destination) {
    const source = card.closest(COLUMN)
    const marker = document.createComment("card before drop")
    const preview = card.cloneNode(true)
    card.replaceWith(marker)
    this.#placePreview(preview, destination)
    this.#adjustCount(source, -1)
    this.#adjustCount(destination, 1)

    // Save in drop order: each move becomes the latest activity in its destination.
    this.#saves = this.#saves.then(async () => {
      try {
        const response = await this.#save(card, destination)
        if (!response.ok || !response.isTurboStream) throw new Error("Card move failed")
        marker.remove()
      } catch {
        if (marker.isConnected && preview.isConnected) {
          preview.remove()
          marker.replaceWith(card)
          this.#adjustCount(source, 1)
          this.#adjustCount(destination, -1)
          window.alert("The card couldn’t be moved. Please try again.")
        }
      }
    })
  }

  #placePreview(card, column) {
    card.setAttribute("aria-busy", "true")
    card.removeAttribute("aria-selected")
    card.draggable = false
    card.querySelector(".card__closed")?.remove()
    card.querySelector(".bubble")?.remove()
    card.classList.remove("card--postponed")
    card.style.setProperty("--card-color", column.style.getPropertyValue("--card-color") || "var(--color-card-default)")

    const active = [ "maybe", "column" ].includes(column.dataset.dropStatus)
    const cards = column.querySelectorAll(CARD)
    const afterGold = active && !card.classList.contains("golden-effect")
    const next = afterGold ? Array.from(cards).find(other => !other.classList.contains("golden-effect")) : cards[0]
    if (next) {
      next.before(card)
    } else if (cards.length) {
      cards[cards.length - 1].after(card)
    } else {
      column.querySelector(".cards__list turbo-frame").prepend(card)
    }
  }

  #adjustCount(column, delta) {
    const counter = column.querySelector(".cards__expander-count")
    const count = Number(counter.dataset.count) + delta
    counter.dataset.count = count
    counter.textContent = count > 99 ? "99+" : count
  }

  #save(card, column) {
    const options = { responseKind: "turbo-stream", query: { card_preview: true } }
    switch (column.dataset.dropStatus) {
      case "column": return post(card.dataset.cardTriageUrl, { ...options, body: { column_id: column.dataset.columnId } })
      case "maybe": return destroy(card.dataset.cardTriageUrl, options)
      case "not-now": return post(card.dataset.cardNotNowUrl, options)
      case "closed": return post(card.dataset.cardClosureUrl, options)
    }
  }
}
require "test_helper"

class CardPreviewBoostCountTest < ActionDispatch::IntegrationTest
  setup do
    sign_in_as :kevin
    @card_with_reactions = cards(:logo)
    @card_without_reactions = cards(:layout)
    @column = @card_with_reactions.column
  end

  test "card preview displays boost count when card has reactions" do
    get board_column_path(@column.board, @column)
    assert_response :success

    # Check that boost count is displayed for cards with reactions
    assert_select ".card__boosts", text: /2/
  end

  test "card preview does not display boost count when card has no reactions" do
    # Ensure layout card is in the same column for this test
    @card_without_reactions.update!(column: @column)

    get board_column_path(@column.board, @column)
    assert_response :success

    # Find the card without reactions and verify no boost count is shown
    # We check the overall page doesn't have a boost count for zero reactions
    # (This is an imperfect test but reasonable given the structure)
    assert @card_without_reactions.reactions.none?
  end
end
"
