module ColumnPagination
  private
    def set_column_page(cards)
      set_page_and_extract_portion_from cards, per_page: column_page_sizes
    end

    # On the board, drops can grow or shrink pages that have already been rendered.
    # Keep the normal gear for the requested page; only its starting offset changes.
    def column_page_sizes
      if turbo_frame_request? && params[:loaded_pages].present?
        sizes = params.expect(:loaded_pages).split(",").map { |size| size.to_i.clamp(0, Current.account.cards_count) }
        if sizes.size == params[:page].to_i - 1
          gears = GearedPagination::Ratios::DEFAULTS
          sizes + (gears.drop(sizes.size).presence || [ gears.last ])
        end
      end
    end
end
module Card::Closeable
  extend ActiveSupport::Concern

  included do
    has_one :closure, dependent: :destroy

    scope :closed, -> { joins(:closure) }
    scope :open, -> { where.missing(:closure) }

    scope :recently_closed_first, -> { closed.order(closures: { created_at: :desc }) }
    scope :closed_at_window, ->(window) { closed.where(closures: { created_at: window }) }
    scope :closed_by, ->(users) { closed.where(closures: { user_id: Array(users) }) }
  end

  def closed?
    closure.present?
  end

  def open?
    !closed?
  end

  def closed_by
    closure&.user
  end

  def closed_at
    closure&.created_at
  end

  def close(user: Current.user)
    unless closed?
      transaction do
        not_now&.destroy
        create_closure! user: user
        track_event :closed, creator: user
      end
    end
  end

  def reopen(user: Current.user)
    if closed?
      transaction do
        closure&.destroy
        track_event :reopened, creator: user
      end
    end
  end
end
